INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um homem de 72 anos, tabagista e hipertenso, no 4º dia de pós-operatório de uma correção de aneurisma de aorta abdominal infra-renal, apresenta queda do débito urinário para 200 mL nas últimas 12 horas. Os exames laboratoriais revelam Creatinina de 2,4 mg/dL (valor pré-op de 1,1 mg/dL) e potássio de 5,8 mEq/L. Qual é a causa mais provável de insuficiência renal aguda (IRA) neste contexto e a medida inicial recomendada?","options":{"a":"Ncrose Tubular Aguda por hipoperfusão severa ou contraste; otimização volêmica e monitorização.","b":"IRA pré-renal por desidratação; hidratação agressiva com 4 litros de soro fisiológico.","c":"Obstrução ureteral bilateral inadvertida; reoperação imediata.","d":"Nefrite intersticial por antibióticos; início de corticoterapia.","e":"Infarto renal bilateral; nefrectomia de urgência."},"answer":"a","rationale":"Em grandes cirurgias vasculares, a IRA costuma ser multifatorial (isquemia-reperfusão, clampeamento aórtico, uso de contraste e hipovolemia), resultando em necrose tubular aguda. O manejo inicial foca na manutenção da euvolemia e evitar novos insultos.","option_rationales":{"a":"Correta. Principal causa pós-trauma cirúrgico maior.","b":"Errada. Embora a hidratação seja importante, 4L em um cardiopata hipertenso pode causar edema pulmonar.","c":"Errada. Raro e causaria anúria súbita, não oligúria.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Complicações Renais"]}', '38f1c152a9f9e4ffbd574abbe67a8aa7', 25, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Paciente de 60 anos, sem comorbidades conhecidas, no 2º dia de pós-operatório de uma gastrectomia total, evolui com dispneia súbita e taquicardia. Ao exame físico, apresenta-se taquipneico (FR 28 irpm), SatO2 88% em ar ambiente, com ausculta pulmonar normal. A radiografia de tórax é normal. Qual é o diagnóstico de exclusão mais importante a ser investigado?","options":{"a":"Pneumonia nosocomial precoce.","b":"Edema agudo de pulmão.","c":"Tromboembolismo Pulmonar (TEP).","d":"Atelectasia de lobo médio.","e":"Pneumotórax hipertensivo."},"answer":"c","rationale":"A tríade de dispneia, taquicardia e radiografia de tórax normal no pós-operatório de grande porte é altamente sugestiva de TEP. A ausculta limpa reforça essa hipótese contra pneumonia ou edema.","option_rationales":{"a":"Errada. Haveria febre e alterações na ausculta/RX.","b":"Errada. Haveria estertores crepitantes e aspas de Kerley no RX.","c":"Correta. Emergência vascular pulmonar frequente após cirurgias oncológicas.","d":"Errada. O RX mostraria opacidade.","e":"Errada. O RX mostraria colapso pulmonar e desvio de traqueia."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","TEP"]}', 'a36874439e27ab5960f446f51bd6ca92', 26, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual dos seguintes parâmetros clínicos é o indicador mais sensível de disfunção respiratória iminente por ''Fadiga Muscular'' em um paciente em desmame ventilatório no pós-operatório?","options":{"a":"Uso de musculatura acessória e respiração paradoxal (balanço tóraco-abdominal).","b":"Queda isolada da PaO2 na gasometria.","c":"Aumento do débito cardíaco.","d":"Bradicardia sinusal.","e":"Poliúria compensatória."},"answer":"a","rationale":"O padrão respiratório paradoxal indica que o diafragma está exausto e a musculatura abdominal está sendo recrutada, sinalizando falha iminente da ventilação.","option_rationales":{"a":"Correta. Exame físico crítico na terapia intensiva cirúrgica.","b":"Errada. A queda da PaO2 pode ser tardia após o início da fadiga.","c":"Errada.","d":"Errada. O esperado é taquicardia por estresse.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Respiratório"]}', 'a5a172acc6c560ee19bfa0cc161769f8', 27, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente de 68 anos, com histórico de cardiopatia isquêmica, apresenta episódios de fibrilação atrial com resposta ventricular alta (140 bpm) no 3º dia de pós-operatório de uma hemicolectomia. O paciente está estável hemodinamicamente, sem dor precordial. Qual a conduta inicial recomendada?","options":{"a":"Cardioversão elétrica imediata com 200J.","b":"Administração de Amiodarona endovenosa para controle de ritmo ou frequência.","c":"Realizar massagem do seio carotídeo apenas.","d":"Prescrever digitálicos (Digoxina) como primeira linha.","e":"Encaminhar para cineangiocoronariografia urgente."},"answer":"b","rationale":"Em pacientes estáveis com FA de início recente no pós-operatório, o controle da frequência ou reversão farmacológica com amiodarona é a conduta padrão. A cardioversão elétrica é reservada para instabilidade.","option_rationales":{"a":"Errada. Indicada se houver hipotensão, edema de pulmão ou isquemia miocárdica.","b":"Correta. Manejo de arritmia supraventricular.","c":"Errada.","d":"Errada. Início de ação lento e toxicidade em idosos.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Cardiovascular"]}', '4c064114ff41063c3f68d6b59f710e5c', 28, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A ''Atelectasia'' no pós-operatório imediato ocorre principalmente devido a:","options":{"a":"Aumento da produção de surfactante pulmonar.","b":"Compressão externa por derrames pleurais maciços em todos os casos.","c":"Fechamento alveolar por redução do volume corrente, dor ao respirar e efeitos dos anestésicos (perda de tônus do diafragma).","d":"Broncoespasmo induzido por estresse.","e":"Excesso de hidratação venosa no peroperatório."},"answer":"c","rationale":"A dor abdominal/torácica impede inspirações profundas, levando ao colabamento alveolar nas bases pulmonares (zonas dependentes).","option_rationales":{"a":"Errada. Ocorre diminuição ou inativação do surfactante.","b":"Errada. Embora o derrame possa causar compressão, não é a causa primária da atelectasia pós-op comum.","c":"Correta. Mecanismo fisiopatológico principal.","d":"Errada.","e":"Errada. Isso causaria edema, não atelectasia primária."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Respiratório"]}', 'fe2ba56530410e1e6352ed341b80b193', 29, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A ''Pneumonia Associada à Ventilação'' (PAV) deve ser suspeitada quando o paciente em ventilação mecânica por mais de 48 horas apresenta:","options":{"a":"Queda súbita da temperatura axilar.","b":"Infiltrado radiológico novo ou progressivo associado a febre e secreção traqueal purulenta.","c":"Melhora nos parâmetros de oxigenação (P/F ratio).","d":"Queda isolada dos leucócitos.","e":"Redução do volume de secreção nasal."},"answer":"b","rationale":"O diagnóstico de PAV requer critérios clínicos (febre, secreção), laboratoriais (leucocitose) e radiológicos (infiltrado).","option_rationales":{"a":"Errada. O esperado é febre (>38°C).","b":"Correta. Definição diagnóstica clássica.","c":"Errada. Ocorre piora da oxigenação.","d":"Errada. Ocorre leucocitose ou leucopenia no contexto de sepse.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Infecção"]}', '525c197adbddaeeaa34d7d582b3213fa', 30, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual a principal medida preventiva para evitar a ''Pneumonia Aspirativa'' em pacientes cirúrgicos com rebaixamento de nível de consciência ou íleo adinâmico?","options":{"a":"Manter o paciente em decúbito dorsal horizontal (0°).","b":"Elevação da cabeceira do leito entre 30 e 45 graus.","c":"Antibioticoterapia profilática oral.","d":"Lavagem gástrica com carvão ativado a cada 6 horas.","e":"Administração de antieméticos de horário, sem outras medidas."},"answer":"b","rationale":"A posição semissentada reduz significativamente o refluxo gastroesofágico e a microaspiração de conteúdo gástrico.","option_rationales":{"a":"Errada. Aumenta drasticamente o risco de aspiração.","b":"Correta. Medida de enfermagem e suporte fundamental.","c":"Errada.","d":"Errada.","e":"Errada. Antieméticos ajudam, mas não substituem a barreira mecânica do posicionamento."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Segurança"]}', '9a247b7ff442a2fa769338c2d57cde6d', 31, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente de 55 anos, diabético, no 4º dia de pós-operatório de gastrectomia, evolui com edema, calor e rubor em panturrilha esquerda, sem dor torácica. O Doppler confirma Trombose Venosa Profunda (TVP) infrapatelar. Qual a conduta terapêutica inicial mais adequada?","options":{"a":"Realizar trombectomia cirúrgica de urgência.","b":"Anticoagulação plena (ex: HBPM ou Heparina Não Fracionada) e observar estabilidade da anastomose.","c":"Apenas mobilização precoce no leito.","d":"Administração isolada de antiagregantes plaquetários (Aspirina).","e":"Colocação de filtro de veia cava superior."},"answer":"b","rationale":"O diagnóstico de TVP exige anticoagulação para prevenir a progressão e o TEP, desde que não haja contraindicação absoluta (sangramento ativo grave).","option_rationales":{"a":"Errada. Reservada para Phlegmasia Cerulea Dolens.","b":"Correta. Manejo de tromboembolismo.","c":"Errada. Insuficiente se o trombo já estiver formado.","d":"Errada. Aspirina não trata TVP estabelecida.","e":"Errada. Filtro de veia cava inferior é indicado se houver contraindicação formal à anticoagulação."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Vascular"]}', '46d738ad2eddeb47d135db4cd67d74b6', 32, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"O ''Infarto Agudo do Miocárdio'' (IAM) no pós-operatório costuma ser atípico. Qual a característica clínica do IAM nesta fase que dificulta o seu diagnóstico precoce?","options":{"a":"Presença de dor precordial intolerável em 100% dos casos.","b":"Frequentemente é indolor (IAM silencioso) devido ao uso de analgésicos e sedativos.","c":"Ocorre apenas durante o ato cirúrgico.","d":"Sempre se manifesta com hipertensão maligna.","e":"Não causa alterações no ECG nas primeiras 24 horas."},"answer":"b","rationale":"A analgesia pós-operatória pode mascarar a dor anginosa. Taquicardia inexplicada, hipotensão ou alterações respiratórias devem levar à suspeita e dosagem de troponina.","option_rationales":{"a":"Errada. Frequentemente é indolor.","b":"Correta. Nuance diagnóstica importante.","c":"Errada. Pico de incidência entre o 1º e 3º dia.","d":"Errada.","e":"Errada. O ECG é dinâmico."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Cardiovascular"]}', '5418673673158a921db901e5e313a6a8', 33, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Em relação à ''Insuficiência Renal Pré-renal'' no pós-operatório, qual é o achado laboratorial urina-plasma esperado na urinálise simplificada?","options":{"a":"Fração de excreção de sódio (FeNa) maior que 2%.","b":"Sódio urinário menor que 20 mEq/L e FeNa menor que 1%.","c":"Presença de cilindros granulosos ''marrom-terra''.","d":"Densidade urinária muito baixa (isostenúria).","e":"Proteinúria maciça (> 3,5 g/dia)."},"answer":"b","rationale":"Na IRA pré-renal, o rim está ávido por sódio e água para tentar restaurar a volemia, resultando em urina concentrada e pobre em sódio.","option_rationales":{"a":"Errada. Sugere NTA (renal).","b":"Correta. Diferenciação laboratorial de IRA.","c":"Errada. Sugere NTA (renal).","d":"Errada.","e":"Errada. Sugere síndrome nefrótica."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Renal"]}', '1c9b6a44113abb7c09309440dd1eda97', 34, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente de 75 anos, no 5º dia de pós-operatório de prostatectomia, desenvolve quadro agudo de agitação, desorientação temporal, inversão do ciclo sono-vigília e alucinações. Os sinais vitais estão estáveis, SatO2 96%, glicemia capilar de 110 mg/dL e sem déficit motor. Qual o diagnóstico e a medida não farmacológica prioritária?","options":{"a":"Acidente Vascular Cerebral (AVC); realizar TC imediata.","b":"Hipoglicemia grave; dar glicose 50%.","c":"Delirium; garantir a presença de acompanhante familiar e reorientação constante do paciente (luz diurna, relógio, óculos/aparelho auditivo).","d":"Abstinência alcoólica; administrar benzodiazepínicos em altas doses.","e":"Demência de Alzheimer instalada subitamente; encaminhar ao asilo."},"answer":"c","rationale":"O delirium é um estado confusional agudo e flutuante muito comum em idosos no pós-operatório. Medidas ambientais são a primeira linha de tratamento.","option_rationales":{"a":"Errada. Ausência de sinais focais e início confusional global favorecem delirium.","b":"Errada. Glicemia normal.","c":"Correta. Manejo geriátrico em cirurgia.","d":"Errada. Benzodiazepínicos podem piorar o delirium, a menos que seja comprovadamente por abstinência (Delirium Tremens).","e":"Errada. Demência não é súbita."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Delirium"]}', '6bb3e3ac0e97d1e9aab41ec538f94311', 35, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A monitorização da ''Pressão Venosa Central'' (PVC) isoladamente não é mais considerada o melhor preditor de volemia. Atualmente, qual é o papel da PVC na monitorização hemodinâmica pós-operatória?","options":{"a":"Não deve ser mais utilizada em nenhuma circunstância.","b":"Serve como alvo terapêutico absoluto (manter > 12 mmHg).","c":"Pode ser utilizada como limite de segurança para interromper a reposição volêmica se houver um aumento abrupto associado a sinais de edema pulmonar.","d":"Sempre reflete a pressão de enchimento do ventrículo esquerdo.","e":"Substitui a necessidade de ecocardiograma."},"answer":"c","rationale":"Embora valores estáticos de PVC não predigam responsividade a fluidos, tendências de aumento rápido podem alertar para sobrecarga de câmaras direitas/insuficiência cardíaca.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Interpretação atual da PVC.","d":"Errada. Reflete o átrio direito.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Monitorização"]}', '53cdce86d16c33b6972aa99afb9ea646', 36, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual dos seguintes fármacos é contraindicado para o controle da dor no pós-operatório de um paciente com insuficiência renal crônica (Creatinina 3,5 mg/dL) devido ao risco de Agravamento da lesão renal?","options":{"a":"Dipirona.","b":"Tramadol.","c":"Cetoprofeno (AINE).","d":"Morfina.","e":"Cloridrato de Petidina."},"answer":"c","rationale":"Os anti-inflamatórios não esteroides (AINEs) inibem as prostaglandinas renais, causando vasoconstrição da arteríola aferente e queda do ritmo de filtração glomerular.","option_rationales":{"a":"Errada. Segura no renal.","b":"Errada. Pode exigir ajuste de dose pela meia-vida, mas não é nefrotóxico direto.","c":"Correta. Nefrotoxicidade clássica.","d":"Errada. Cuidado apenas com acúmulo de metabólitos ativos (sedação).","e":"Errada. Cuidado com metabólito (normeperidina) que causa convulsões no renal, mas não é a principal contraindicação renal pura."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Farmacologia"]}', '3c36e20f8faf40b8c9eb296973a65be2', 37, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente tabagista com DPOC será submetido a uma gastrectomia. Qual medida de ''Fisioterapia Respiratória'' no pré e pós-operatório é a mais eficaz para reduzir a incidência de complicações respiratórias?","options":{"a":"Uso de espirômetro de incentivo isoladamente sem acompanhamento.","b":"Cessação do tabagismo pelo menos 4 a 8 semanas antes da cirurgia e exercícios de expansão pulmonar inspiratórios.","c":"Manter oxigenioterapia em alto fluxo para todos os pacientes DPOC.","d":"Prescrever apenas broncodilatadores durante o ato cirúrgico.","e":"Repouso após a cirurgia para poupar os pulmões."},"answer":"b","rationale":"A cessação precoce do tabagismo limpa vias aéreas e melhora a função ciliar. Exercícios respiratórios ativos são superiores ao repouso.","option_rationales":{"a":"Errada. O espirômetro sozinho é igual à respiração profunda orientada.","b":"Correta. Manejo preventivo padrão.","c":"Errada. Oxigênio em excesso no DPOC pode deprimir o drive respiratório.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Respiratório"]}', '2bb3eede1a166729072f619be4a1b089', 38, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente de 40 anos, após uma tireoidectomia total, apresenta espasmo muscular na mão após o insuflamento do manguito de pressão arterial acima da pressão sistólica por 3 minutos. Como se chama este sinal e qual a causa provável?","options":{"a":"Sinal de Chvostek; Hipocalcemia.","b":"Sinal de Trousseau; Hipocalcemia.","c":"Sinal de Murphy; Colecistite.","d":"Sinal de Babinski; Lesão medular.","e":"Sinal de Blumberg; Peritonite."},"answer":"b","rationale":"O sinal de Trousseau indica irritabilidade neuromuscular secundária à hipocalcemia (comum após lesão ou remoção acidental de paratireoides em cirurgias de pescoço).","option_rationales":{"a":"Errada. Chvostek é a contração da face ao percutir o nervo facial.","b":"Correta. Semiologia endócrina pós-op.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Eletrólitos"]}', '8228736d9b459fa7b2de9eca7447be0b', 39, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Sobre o manejo da ''Hipotensão'' no pós-operatório imediato, qual o primeiro passo diagnóstico após garantir a via aérea e oxigenação?","options":{"a":"Iniciar vasopressores (Noradrenalina) imediatamente em todos os casos.","b":"Avaliar o estado volêmico (perdas intraoperatórias, débito de drenos) e realizar prova de carga volêmica se indicado.","c":"Prescrever digitálicos para melhorar a contratilidade.","d":"Solicitar angiografia de corpo inteiro.","e":"Administrar 10 bolsas de sangue antes de examinar o paciente."},"answer":"b","rationale":"A causa mais comum de hipotensão no pós-operatório é a hipovolemia (sangramento ou reposição insuficiente). A prova de carga é diagnóstica e terapêutica.","option_rationales":{"a":"Errada. Pode piorar a isquemia renal se o paciente estiver hipovolêmico.","b":"Correta. Passo primordial no choque.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Choque"]}', '1aa695250e95f907c31aa927d889f8c4', 40, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual complicação cardiovascular é a principal causa de morte em pacientes submetidos a cirurgias não cardíacas de grande porte no primeiro mês de pós-operatório?","options":{"a":"Tromboembolismo Pulmonar tardio.","b":"Eventos Cardíacos Adversos Maiores (MACE), como o IAM.","c":"Insucesso da anestesia.","d":"Endocardite bacteriana aguda.","e":"Aneurisma de ventrículo."},"answer":"b","rationale":"A morbidade cardiovascular é a principal preocupação em pacientes cirúrgicos, especialmente os de risco moderado a alto (Escala de Lee).","option_rationales":{"a":"Errada. Embora grave, o IAM é mais frequente e fatal globalmente.","b":"Correta. Cardiologia cirúrgica.","c":"Errada.","d":"Errada. Rara no pós-op imediato.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Estatística"]}', 'd668c43029185ce7d9f148d47b1999cf', 41, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Em relação à ''Insuficiência Renal Aguda Pós-renal'', qual é o achado radiológico mais comum na ultrassonografia de rins e vias urinárias?","options":{"a":"Rins ecogênicos e reduzidos.","b":"Dilatação do sistema coletor (hidronefrose) e eventual identificação do ponto de obstrução.","c":"Ausência de vasos renais ao Doppler.","d":"Cistos renais simples.","e":"Ureterocele associada a cálculo coraliforme."},"answer":"b","rationale":"A causa pós-renal é obstrutiva (litíase, tumores, ligadura acidental de ureter). A hidronefrose é o sinal patognomônico de obstrução a jusante.","option_rationales":{"a":"Errada. Sugere DRC crônica.","b":"Correta. Diagnóstico por imagem em IRA.","c":"Errada. Sugere causa vascular.","d":"Errada.","e":"Errada. Específico de determinada patologia, não um achado ''geral'' de toda IRA pós-renal."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Imaginologia"]}', '5ced8ff78fb5ffddf392c5fe4bb61cc6', 42, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A ''Rabdomiólise'' pode causar IRA no pós-operatório de cirurgias muito prolongadas e com posicionamentos que comprimem grandes massas musculares. Qual o mecanismo da lesão renal causada pela mioglobina?","options":{"a":"Indução de trombose da veia renal.","b":"Toxicidade direta tubular e obstrução dos túbulos por cilindros de mioglobina.","c":"Aumento do pH urinário causando cristais.","d":"Estimulação de autoanticorpos contra o glomérulo.","e":"Queda na produção de eritropoetina."},"answer":"b","rationale":"A pigmento-nefropatia causa vasoconstrição renal e formação de detritos intratubulares que bloqueiam o fluxo de urina.","option_rationales":{"a":"Errada.","b":"Correta. Fisiopatologia da IRA por esmagamento/posicionamento.","c":"Errada. Ocorre acidúria.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Renal"]}', '966a09e9b2dc252e51d0d1f5d3765cf2', 43, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual dos seguintes parâmetros respiratórios é o mais importante para decidir a extubação de um paciente cirúrgico que foi mantido em ventilação mecânica prolongada?","options":{"a":"Frequência respiratória acima de 35 irpm.","b":"Paciente cooperativo, estável hemodinamicamente, com reflexo de tosse e índice de Tobin (f/Vt) menor que 105.","c":"PaO2 de 60 mmHg com FiO2 de 100%.","d":"Uso de sedação contínua em dose máxima.","e":"Ausência completa de secreção respiratória."},"answer":"b","rationale":"O índice de respiração rápida e superficial (Tobin) é o teste preditivo mais confiável de sucesso na extubação.","option_rationales":{"a":"Errada. Contraindica a extubação.","b":"Correta. Critérios de desmame ventilatório.","c":"Errada. Hipóxia grave.","d":"Errada.","e":"Errada. A secreção deve ser manejável, mas raramente é zero."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Intensivismo"]}', '970836f63a3abd977d037e37690fe6c5', 44, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A ''Fibrilação Atrial'' pós-operatória tem pico de incidência em qual janela temporal após a cirurgia?","options":{"a":"Nos primeiros 15 minutos de indução anestésica.","b":"Entre o 2º e o 4º dia de pós-operatório.","c":"Após 30 dias da alta hospitalar.","d":"Exclusivamente no intraoperatório.","e":"Entre o 10º e 15º dia."},"answer":"b","rationale":"O estresse simpático, as alterações hidroeletrolíticas e o estado inflamatório atingem seu ápice radiológico e clínico nessa janela.","option_rationales":{"a":"Errada.","b":"Correta. Cronologia das complicações.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Arritmias"]}', 'ee5d73c993a54ccf5ca1e5f90ad07dd0', 45, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente submetido a cirurgia abdominal desenvolve um quadro de ''Laringoespasmo'' imediatamente após a extubação no centro cirúrgico. Qual a conduta inicial prioritária?","options":{"a":"Administrar 500 mL de soro fisiológico.","b":"Pressão positiva contínua em via aérea cam máscara e ambu (CPAP) e se necessário doses baixas de sucinilcolina.","c":"Realizar traqueostomia de urgência no leito.","d":"Aplicar gelo na garganta do paciente.","e":"Induzir vômito para limpar a via aérea."},"answer":"b","rationale":"O laringoespasmo é uma oclusão reflexa da glote. A pressão positiva pode ''vencer'' a resistência das pregas vocais.","option_rationales":{"a":"Errada.","b":"Correta. Manejo de emergência respiratória pós-anestésica.","c":"Errada. Apenas em falha total de manejo conservador/sucinilcolina.","d":"Errada.","e":"Errada. Risco de aspiração catastrófica."},"difficulty":"Difícil","tags":["Anestesiologia","Pós-operatório","Via Aérea"]}', '56b72819770e28a7e4eec8889ed1eaa6', 46, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A ''Escala de Aldrete e Kroulik'' modificada é utilizada para avaliar o quê no pós-operatório imediato?","options":{"a":"Risco de infecção de ferida.","b":"Condições de alta da Sala de Recuperação Pós-Anestésica (SRPA).","c":"Necessidade de nutrição parenteral.","d":"Estágio de um câncer gástrico.","e":"Classificação de hérnias inguinais."},"answer":"b","rationale":"Avalia parâmetros como atividade, respiração, circulação, consciência e saturação de O2 para permitir que o paciente vá para a enfermaria com segurança.","option_rationales":{"a":"Errada.","b":"Correta. Índice de prontidão clínica pós-anestésica.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anestesiologia","Pós-operatório","Escores"]}', 'fbc4135aa7781e22d4f28ce76140b741', 47, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente idoso, no 3º dia de pós-operatório (PO) de fratura de fêmur, apresenta hipoxemia, petéquias em tórax e pescoço, e sinais de confusão mental. Qual a hipótese diagnóstica mais provável?","options":{"a":"TEP maciço.","b":"Pneumonia nosocomial.","c":"Síndrome da Embolia Gordurosa.","d":"Meningite bacteriana.","e":"Tamponamento cardíaco."},"answer":"c","rationale":"A tríade clássica de Gurd (disfunção respiratória, cerebral e petéquias) em paciente com fratura de ossos longos é patognomônica da embolia gordurosa.","option_rationales":{"a":"Errada. TEP não costuma causar petéquias cutâneas.","b":"Errada.","c":"Correta. Diagnóstico diferencial em ortopedia/cirurgia geral.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Embolia Gordurosa"]}', '5309714b50308899e950dc17ce54f030', 48, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A utilização de ''Cateter Arterial'' (invasivo) no pós-operatório é indicada para:","options":{"a":"Medir a PVC.","b":"Monitorização contínua e fidedigna da pressão arterial ciclo a ciclo e coletas frequentes de gasometria.","c":"Administrar drogas vasoativas em alta concentração.","d":"Medir o débito urinário.","e":"Substituir o ventilador mecânico."},"answer":"b","rationale":"A pressão arterial invasiva (PAI) é superior à manguito em pacientes instáveis e permite monitorização de tendências e deltaPP.","option_rationales":{"a":"Errada. (Cateter venoso central).","b":"Correta. Monitorização em terapia intensiva.","c":"Errada. Drogas vasoativas devem ser feitas em veia profunda (central), nunca em artéria.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Monitorização"]}', '1e82738389d5cb1c1d89e6a893d2e091', 49, 'draft');